const r = $input.first().json;

const num = (v) => (v === null || v === undefined ? null : Number(v));
const int = (v) => Number(v || 0);
/** Variacion porcentual con un decimal. null cuando no hay base de comparacion. */
const pct = (cur, prev) => {
  const p = Number(prev || 0);
  if (!p) return null;
  return Math.round(((Number(cur || 0) - p) / p) * 1000) / 10;
};

// Vacio no es cero: mientras no haya un solo gasto cargado, gastos y resultado van en null
// para que la UI muestre "sin datos" y no "$ 0".
const sinGastos = int(r.gas_filas) === 0;

return [{ json: {
  fecha_servidor: r.fecha_servidor,
  sede_id: r.sede_id ?? null,
  currency: r.currency,
  // Los montos por sede salen de la heuristica de cita mas cercana, no de invoices.sede_id.
  sede_source: 'estimated',
  produccion: {
    hoy: num(r.prod_hoy),
    mes: num(r.prod_mes),
    var_dia_pct: pct(r.prod_hoy, r.prod_dia_ant),
    var_mes_pct: pct(r.prod_mes, r.prod_mes_ant),
    mes_anterior: num(r.prod_mes_ant),
  },
  cobranza: {
    hoy: num(r.cob_hoy),
    mes: num(r.cob_mes),
    var_dia_pct: pct(r.cob_hoy, r.cob_dia_ant),
    var_mes_pct: pct(r.cob_mes, r.cob_mes_ant),
    // payments no tiene via a la sede: el valor es siempre consolidado.
    disponible_por_sede: false,
  },
  gastos: {
    hoy: sinGastos ? null : num(r.gas_hoy),
    mes: sinGastos ? null : num(r.gas_mes),
    sin_datos: sinGastos,
  },
  resultado: {
    hoy: sinGastos ? null : num(r.cob_hoy) - num(r.gas_hoy),
    mes: sinGastos ? null : num(r.cob_mes) - num(r.gas_mes),
    sin_datos: sinGastos,
  },
  pacientes_atendidos: {
    hoy: int(r.pac_hoy),
    mes: int(r.pac_mes),
    var_dia_abs: int(r.pac_hoy) - int(r.pac_dia_ant),
    var_mes_pct: pct(r.pac_mes, r.pac_mes_ant),
    agendados_hoy: int(r.agendados_hoy),
  },
  atenciones: {
    hoy: int(r.at_hoy),
    mes: int(r.at_mes),
    var_dia_abs: int(r.at_hoy) - int(r.at_dia_ant),
    var_mes_pct: pct(r.at_mes, r.at_mes_ant),
    agendados_hoy: int(r.agendados_hoy),
  },
  pacientes_nuevos: {
    mes: int(r.nue_mes),
    var_pct: pct(r.nue_mes, r.nue_mes_ant),
  },
} }];

const rows = $input.all().map((i) => i.json);

return [{ json: {
  sede_source: 'estimated',
  total: rows.reduce((s, r) => s + Number(r.produccion || 0), 0),
  rows: rows.map((r) => ({
    sede_id: Number(r.sede_id),
    name: r.name,
    produccion: Number(r.produccion || 0),
    pacientes: Number(r.pacientes || 0),
    atenciones: Number(r.atenciones || 0),
    no_show: Number(r.no_show || 0),
    ticket_promedio: r.ticket_promedio === null || r.ticket_promedio === undefined
      ? null : Number(r.ticket_promedio),
    pct: r.pct === null || r.pct === undefined ? 0 : Number(r.pct),
  })),
} }];

const rows = $input.all().map((i) => i.json);
const granularity = rows[0]?.granularity ?? 'day';

// El promedio se calcula sobre los periodos con actividad: incluir los domingos cerrados
// hundiria el promedio y daria una lectura falsa del ritmo de la clinica.
const activos = rows.filter((r) => Number(r.pacientes || 0) > 0);
const media = (campo) =>
  activos.length
    ? Math.round(activos.reduce((s, r) => s + Number(r[campo] || 0), 0) / activos.length)
    : 0;
const promedio = media('pacientes');
const promedioAtenciones = media('atenciones');

return [{ json: {
  granularity,
  promedio,
  promedio_atenciones: promedioAtenciones,
  periodos_con_actividad: activos.length,
  rows: rows.map((r) => ({
    fecha_inicio: r.fecha_inicio,
    fecha_fin: r.fecha_fin,
    pacientes: Number(r.pacientes || 0),
    nuevos: Number(r.nuevos || 0),
    recurrentes: Number(r.recurrentes || 0),
    atenciones: Number(r.atenciones || 0),
    atenciones_nuevos: Number(r.atenciones_nuevos || 0),
    atenciones_recurrentes: Number(r.atenciones_recurrentes || 0),
    es_actual: r.es_actual === true,
  })),
} }];

const rows = $input.all().map((i) => i.json);
const total = Number(rows[0]?.total_periodo || 0);

// Paleta --chart-1..5 de globals.css, en el mismo formato hsl(var(--chart-N)) que usa el resto
// de los graficos, para que la tarjeta siga los temas claro/oscuro.
const COLORS = [
  'hsl(var(--chart-5))', 'hsl(var(--chart-3))', 'hsl(var(--chart-2))',
  'hsl(var(--chart-4))', 'hsl(var(--chart-1))',
];

return [{ json: {
  total,
  rows: rows.map((r, idx) => ({
    name: r.name,
    sales: Number(r.sales || 0),
    percentage: total ? Math.round((Number(r.sales || 0) / total) * 1000) / 10 : 0,
    color: COLORS[idx % COLORS.length],
  })),
} }];

const rows = $input.all().map((i) => i.json);

const num = (v) => (v === null || v === undefined ? null : Number(v));
/** Variacion porcentual con un decimal. null cuando no hay base de comparacion. */
const pct = (cur, prev) => {
  const p = Number(prev || 0);
  if (!p) return null;
  return Math.round(((Number(cur || 0) - p) / p) * 1000) / 10;
};

// Vacio no es cero, y se evalua mes a mes: un mes sin una sola fila de gasto va en null
// para que la celda muestre un guion, no un "$ 0" que se leeria como "no hubo gastos".
// La metrica entera se marca sin_datos solo si ningun mes de la ventana tiene gastos.
const tieneGastos = (r) => Number(r.gastos_filas || 0) > 0;
const hayGastos = rows.some(tieneGastos);

const meses = rows.map((r) => ({
  mes: r.mes,
  inicio: r.mes_inicio,
  fin: r.mes_fin,
  es_parcial: r.es_parcial === true,
}));

const METRICAS = [
  { key: 'produccion', tipo: 'moneda' },
  { key: 'cobranza',   tipo: 'moneda' },
  { key: 'atenciones', tipo: 'conteo' },
  { key: 'pacientes',  tipo: 'conteo' },
  { key: 'nuevos',     tipo: 'conteo' },
  { key: 'gastos',     tipo: 'moneda' },
];

const metricas = METRICAS.map(({ key, tipo }) => {
  const sinDatos = key === 'gastos' && !hayGastos;
  const valores = rows.map((r) =>
    key === 'gastos' && !tieneGastos(r) ? null : sinDatos ? null : num(r[key]),
  );

  // La variacion del ultimo mes: si esta en curso se compara contra el mismo tramo de dias
  // del mes anterior; si esta cerrado, contra el mes anterior completo.
  const ult = rows[rows.length - 1];
  const prev = rows[rows.length - 2];
  let varPct = null;
  if (!sinDatos && ult) {
    varPct = ult.es_parcial === true
      ? pct(ult[key], ult[key + '_ant_alineada'])
      : pct(ult[key], prev ? prev[key] : null);
  }

  return { key, tipo, valores, var_pct: varPct, sin_datos: sinDatos };
});

return [{ json: { meses, metricas } }];
